  private void verifyLicense(){message("Đang xác nhận Studio Pro…");NativeApi.shared.call("GET","/api/store",null,(catalog,error,code)->{if(closed)return;if(error!=null||catalog==null){message("Chưa xác nhận được gói. Kiểm tra mạng rồi thử lại.");if(project==null){controls.removeAllViews();controls.addView(text("Chưa xác nhận được gói. Kiểm tra mạng rồi thử lại.",14,MUTED));controls.addView(button("Thử lại",this::verifyLicense));controls.addView(button("Đóng",this::finish));}return;}acceptCatalog(catalog);});}
  private void acceptCatalog(JSONObject catalog){String next=catalog.optString("accountId");if(next.isEmpty()){message("Vui lòng đăng nhập lại.");return;}if(!account.isEmpty()&&!account.equals(next)){finish();return;}account=next;licensed=false;JSONArray owned=catalog.optJSONArray("owned");for(int i=0;owned!=null&&i<owned.length();i++)if("kinnect_studio_pro".equals(owned.optString(i)))licensed=true;licenseSession=NativeApi.shared.jar();modeLabel.setText(tr(licensed?"Ảnh":"Xem thử"));folder=new File(getFilesDir(),"photo-projects/"+Integer.toHexString(account.hashCode())+"-"+account.replaceAll("[^a-zA-Z0-9]","").substring(0,Math.min(24,account.replaceAll("[^a-zA-Z0-9]","").length())));if(!folder.exists()&&!folder.mkdirs()){message("Không lưu được bản nháp.");return;}draft=new File(folder,"draft.json");if(project!=null||loading)return;if(draft.isFile())new Sheet(this).setTitle(tr("Tiếp tục bản nháp?")).setMessage(tr("Bản nháp gần nhất vẫn giữ ảnh gốc và các lớp chỉnh sửa.")).setPositiveButton(tr("Tiếp tục"),(d,w)->restoreDraft()).setNegativeButton(tr("Ảnh mới"),(d,w)->openNew()).show();else openNew();}
  private boolean permitted(){return licensed&&!licenseSession.isEmpty()&&licenseSession.equals(NativeApi.shared.jar());}
  private File importImage(Uri uri)throws IOException {File file=File.createTempFile("source-",".image",folder);boolean ok=false;try(InputStream in=getContentResolver().openInputStream(uri);FileOutputStream out=new FileOutputStream(file)){if(in==null)throw new IOException("Không mở được ảnh.");byte[] bytes=new byte[65536];long size=0;for(int n;(n=in.read(bytes))!=-1;){size+=n;if(size>64L*1024*1024)throw new IOException("Chọn ảnh nhỏ hơn 64 MB.");out.write(bytes,0,n);}out.getFD().sync();ok=true;}finally{if(!ok)file.delete();}Bitmap test=null;try{test=PhotoRenderer.decode(file,256);return file;}catch(IOException|RuntimeException e){file.delete();throw e;}finally{if(test!=null)test.recycle();}}
  private void openNew(){if(loading)return;loading=true;message("Đang mở ảnh…");io.execute(()->{try{File source=importImage(initialUri);Bitmap image=PhotoRenderer.decode(source,4096);PhotoProject fresh=new PhotoProject();fresh.width=image.getWidth();fresh.height=image.getHeight();fresh.originalSource=source.getPath();image.recycle();PhotoProject.Layer base=new PhotoProject.Layer();base.name=tr("Ảnh nền");base.source=source.getPath();base.locked=false;fresh.layers.add(base);fresh.selected=base.id;ui.post(()->{if(closed)return;loading=false;project=fresh;pruneBefore=source.lastModified();undo.clear();redo.clear();renderControls();changed();});}catch(IOException|RuntimeException|OutOfMemoryError e){ui.post(()->{loading=false;message("Không mở được ảnh. Hãy chọn ảnh nhỏ hơn.");});}});}
  private void restoreDraft(){if(loading)return;loading=true;io.execute(()->{try{if(draft.length()>4*1024*1024)throw new IOException();String saved=new String(read(draft),"UTF-8");JSONObject data=new JSONObject(saved);PhotoProject restored=PhotoProject.decode(data.getString("project"));String prefix=folder.getCanonicalPath()+File.separator;if(!new File(restored.originalSource).getCanonicalPath().startsWith(prefix)||!new File(restored.originalSource).isFile())throw new IOException();for(PhotoProject.Layer l:restored.layers)if(l.kind.equals("image")&&(!new File(l.source).getCanonicalPath().startsWith(prefix)||!new File(l.source).isFile()))throw new IOException();ui.post(()->{if(closed)return;loading=false;project=restored;undo.clear();redo.clear();try{JSONArray history=data.optJSONArray("undo");for(int i=0;history!=null&&i<history.length();i++){PhotoProject prior=PhotoProject.decode(history.getString(i));boolean safe=true;for(PhotoProject.Layer layer:prior.layers)if(layer.kind.equals("image")&&!new File(layer.source).getCanonicalPath().startsWith(prefix))safe=false;if(safe)undo.addLast(prior.encode());}}catch(Exception ignored){}renderControls();requestRender();message("Đã mở lại bản nháp.");});}catch(Exception e){ui.post(()->{loading=false;new Sheet(this).setTitle(tr("Không mở được bản nháp")).setMessage(tr("Ảnh gốc của bản nháp không còn đầy đủ. Bạn có thể mở ảnh mới.")).setPositiveButton(tr("Ảnh mới"),(d,w)->openNew()).setNegativeButton(tr("Đóng"),(d,w)->finish()).show();});}});}
