  private void remember(){if(project==null)return;undo.addLast(project.encode());while(undo.size()>30)undo.removeFirst();redo.clear();}
  private void history(boolean forward){ArrayDeque<String> from=forward?redo:undo,to=forward?undo:redo;if(project==null||from.isEmpty())return;try{to.addLast(project.encode());project=PhotoProject.decode(from.removeLast());renderControls();changed();}catch(JSONException e){message("Không mở được bản nháp.");}}
