  private final Runnable saveTask=this::saveDraft;
  private void saveDraft(){if(discardOnExit)return;if(project==null||draft==null||io.isShutdown())return;final String value=project.encode();final ArrayList<String> history=new ArrayList<>();int historySize=0;Iterator<String> recent=undo.descendingIterator();while(recent.hasNext()&&history.size()<8){String prior=recent.next();if(historySize+prior.length()>512000)break;history.add(0,prior);historySize+=prior.length();}final long prune=pruneBefore;final File target=draft;io.execute(()->{try{JSONObject data=new JSONObject().put("project",value).put("undo",new JSONArray(history));android.util.AtomicFile file=new android.util.AtomicFile(target);FileOutputStream stream=null;try{stream=file.startWrite();stream.write(data.toString().getBytes("UTF-8"));file.finishWrite(stream);if(prune>0){File[] old=target.getParentFile().listFiles();for(File source:old==null?new File[0]:old)if(source.isFile()&&source.getName().startsWith("source-")&&source.lastModified()<prune)source.delete();}}catch(Exception e){if(stream!=null)file.failWrite(stream);throw e;}ui.post(()->{if(pruneBefore==prune)pruneBefore=0;if(!busy)message(licensed?"Đã lưu bản nháp trên máy.":"Xem thử · xuất ảnh cần Studio Pro.");});}catch(Exception e){ui.post(()->message("Không lưu được bản nháp."));}});}
  private void requestRender(){if(project==null||closed||renderer.isShutdown())return;final int version=++renderVersion;final PhotoProject copy=project.copy();renderer.execute(()->{if(version!=renderVersion||closed)return;try{Bitmap next=PhotoRenderer.render(this,copy,900);ui.post(()->{if(closed||version<shownVersion){next.recycle();return;}shownVersion=version;Bitmap previous=rendered;rendered=next;canvas.display=next;canvas.invalidate();if(previous!=null&&previous!=canvas.original&&!previous.isRecycled())previous.recycle();updateHistory();});}catch(IOException|RuntimeException|OutOfMemoryError e){ui.post(()->message("Chưa dựng được ảnh. Giảm số lớp hoặc chọn ảnh nhỏ hơn."));}});}
  private void updateHistory(){undoButton.setAlpha(undo.isEmpty()?.35f:1);redoButton.setAlpha(redo.isEmpty()?.35f:1);}
  private void slider(LinearLayout into,String name,int value,int min,int max,java.util.function.IntConsumer change){LinearLayout label=row();label.addView(text(name,12,MUTED),new LinearLayout.LayoutParams(0,-2,1));TextView number=text(String.valueOf(value),12,INK);label.addView(number);into.addView(label);SeekBar seek=new SeekBar(this);seek.setMax(max-min);seek.setProgress(value-min);seek.setProgressTintList(ColorStateList.valueOf(ACCENT));seek.setThumbTintList(ColorStateList.valueOf(ACCENT));seek.setContentDescription(tr(name));seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){boolean started;public void onStartTrackingTouch(SeekBar v){if(busy)return;remember();started=true;}public void onProgressChanged(SeekBar v,int progress,boolean user){if(!user||busy)return;if(!started){remember();started=true;}number.setText(String.valueOf(progress+min));change.accept(progress+min);requestRender();}public void onStopTrackingTouch(SeekBar v){started=false;changed();}});into.addView(seek,new LinearLayout.LayoutParams(-1,dp(36)));}
