  private void crop(float ratio){remember();project.left=project.top=0;project.right=project.bottom=1;if(ratio>0){float current=(float)project.width/project.height;if(current>ratio){float width=ratio/current;project.left=(1-width)/2;project.right=1-project.left;}else{float height=current/ratio;project.top=(1-height)/2;project.bottom=1-project.top;}}canvas.resetView();changed();}
