    void compare(boolean show){compare=show;if(show&&original==null&&project!=null){final String source=project.originalSource;io.execute(()->{try{Bitmap image=PhotoRenderer.decode(new File(source),900);ui.post(()->{if(closed){image.recycle();return;}original=image;invalidate();});}catch(Exception ignored){}});}invalidate();}
    private Matrix imageFit(Bitmap image){float scale=Math.min((getWidth()-dp(12))/(float)image.getWidth(),(getHeight()-dp(12))/(float)image.getHeight())*zoom;Matrix m=new Matrix();m.setScale(scale,scale);m.postTranslate((getWidth()-image.getWidth()*scale)/2+panX,(getHeight()-image.getHeight()*scale)/2+panY);return m;}
    protected void onDraw(Canvas c){super.onDraw(c);Bitmap image=compare&&original!=null?original:display;if(image==null||image.isRecycled()){p.setColor(MUTED);p.setTextSize(dp(14));p.setTextAlign(Paint.Align.CENTER);c.drawText(tr("Đang mở ảnh…"),getWidth()/2f,getHeight()/2f,p);return;}fitted.set(imageFit(image));RectF area=new RectF(0,0,image.getWidth(),image.getHeight());fitted.mapRect(area);int cell=dp(12);c.save();c.clipRect(area);for(int y=Math.max(0,(int)area.top);y<Math.min(getHeight(),area.bottom);y+=cell)for(int x=Math.max(0,(int)area.left);x<Math.min(getWidth(),area.right);x+=cell){p.setColor(((x/cell+y/cell)&1)==0?0xff3a3544:0xff292431);c.drawRect(x,y,x+cell,y+cell,p);}c.drawBitmap(image,fitted,null);c.restore();if(!maskMode.equals("off")&&project!=null){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1.5f));p.setColor(ACCENT);c.drawCircle(lastX,lastY,Math.max(dp(8),brush*area.width()/2),p);p.setStyle(Paint.Style.FILL);if(stroke!=null){p.setColor(0x887c5cff);p.setStrokeWidth(Math.max(dp(2),brush*area.width()));p.setStrokeCap(Paint.Cap.ROUND);for(int i=2;i+1<stroke.points.size();i+=2){float[] a=localToScreen(stroke.points.get(i-2),stroke.points.get(i-1)),b=localToScreen(stroke.points.get(i),stroke.points.get(i+1));c.drawLine(a[0],a[1],b[0],b[1],p);}}} }
    private Matrix documentMatrix(){PhotoRenderer.Layout l=PhotoRenderer.layout(project,900);Matrix m=new Matrix(l.matrix);m.postConcat(fitted);return m;}
    private Matrix layerMatrix(PhotoProject.Layer layer){PhotoRenderer.Layout l=PhotoRenderer.layout(project,900);Matrix local=new Matrix();local.postTranslate(-l.docW/2,-l.docH/2);local.postScale(layer.scale,layer.scale);local.postRotate(layer.angle);local.postTranslate(layer.x*l.docW,layer.y*l.docH);local.postConcat(documentMatrix());return local;}
